-- ════════════════════════════════════════════════════════════════════
--  FISIOMARCA · Instalación completa de la base de datos (primera vez)
-- ════════════════════════════════════════════════════════════════════
--  Cómo usarlo:
--    · MySQL Workbench: abrir este archivo y ejecutar todo (rayo ⚡).
--    · Consola:  mysql -u root -pmysql < SQL/01-fisiomarca.sql
--    · Docker:   se ejecuta solo al crear el contenedor MySQL (docker-compose.yml).
--  Después ejecuta SQL/02-estados-pagos.sql (pagos pendientes, expiradas y canceladas).
--
--  BORRA y vuelve a crear las 4 bases de FisioMarca. No toca otras bases.
--
--  Cuentas listas para entrar en http://localhost:3000/login
--    · Administrador:   admin@fisiomarca.com / Admin123
--    · 20 pacientes:    <nombre.apellido>@pacientes.fisiomarca.pe / Paciente123
--                       (ej. lucia.fernandez@pacientes.fisiomarca.pe)
--
--  Datos de demostración (fechas relativas al día en que se ejecuta):
--    · 282 citas en 12 semanas + hoy + próximos 7 días (sin domingos).
--    · 75 % compradas online (orden FM-…, Tarjeta / Yape / Plin), el resto en sede.
--    · 112 notas clínicas (el dolor EVA baja sesión a sesión).
--    · 3 citas en "Pago pendiente": vencen 10 min después de ejecutar el script
--      y pasan solas a "Expiradas" (así se ve el ciclo completo). 8 compras abandonadas.
--    · Reglas respetadas: 1 sesión por día por paciente, máx. 4 citas activas,
--      sin choques de fisioterapeuta ni de sala.
--  Las horas se guardan en UTC (Perú = UTC-5), igual que el backend.
-- ════════════════════════════════════════════════════════════════════

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS fisiomarca_usuarios;
DROP DATABASE IF EXISTS fisiomarca_catalogo;
DROP DATABASE IF EXISTS fisiomarca_reservas;
DROP DATABASE IF EXISTS fisiomarca_carrito;

CREATE DATABASE fisiomarca_usuarios DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE fisiomarca_catalogo DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE fisiomarca_reservas DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE fisiomarca_carrito  DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;


-- ────────────────────────────────────────────────────────────────────
--  1. USUARIOS (AUTH-SERVICE)
-- ────────────────────────────────────────────────────────────────────
USE fisiomarca_usuarios;

CREATE TABLE clientes (
  id int NOT NULL AUTO_INCREMENT,
  email varchar(120) DEFAULT NULL,
  fecha_creacion datetime(6) NOT NULL,
  nombre_completo varchar(120) NOT NULL,
  telefono varchar(20) DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY UK1c96wv36rk2hwui7qhjks3mvg (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE usuarios (
  id int NOT NULL AUTO_INCREMENT,
  activo bit(1) NOT NULL,
  email varchar(120) NOT NULL,
  fecha_creacion datetime(6) NOT NULL,
  nombre_completo varchar(120) NOT NULL,
  password_hash varchar(100) NOT NULL,
  rol varchar(30) NOT NULL,
  cliente_id int DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY UKkfsp0s1tflm1cwlj8idhqsad0 (email),
  UNIQUE KEY UKsuh64qcx0h83ynm45sm2r2lk7 (cliente_id),
  CONSTRAINT FKdx76w4skuwj8wldmr7ebfyegq FOREIGN KEY (cliente_id) REFERENCES clientes (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Administrador + Israel + 20 pacientes de prueba



-- ────────────────────────────────────────────────────────────────────
--  2. CATÁLOGO (Micro-Catalogo y Micro-Soap)
-- ────────────────────────────────────────────────────────────────────
USE fisiomarca_catalogo;

CREATE TABLE categorias (
  id int NOT NULL AUTO_INCREMENT,
  activo bit(1) NOT NULL,
  descripcion varchar(250) DEFAULT NULL,
  imagen_url varchar(255) DEFAULT NULL,
  nombre varchar(100) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY UKqcog8b7hps1hioi9onqwjdt6y (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE servicios (
  id int NOT NULL AUTO_INCREMENT,
  activo bit(1) NOT NULL,
  descripcion varchar(255) DEFAULT NULL,
  duracion_minutos int NOT NULL,
  imagen_url varchar(255) DEFAULT NULL,
  nombre varchar(120) NOT NULL,
  precio decimal(10,2) NOT NULL,
  categoria_id int DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY UKlu7evqbgflb102gqcmbg8y8mf (nombre),
  KEY FK6huyxw0ybs3lb0wdx37oumeq9 (categoria_id),
  CONSTRAINT FK6huyxw0ybs3lb0wdx37oumeq9 FOREIGN KEY (categoria_id) REFERENCES categorias (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;




-- ────────────────────────────────────────────────────────────────────
--  3. RESERVAS, PAGOS, EQUIPO E HISTORIAL (Micro-Reservas)
-- ────────────────────────────────────────────────────────────────────
USE fisiomarca_reservas;

CREATE TABLE fisioterapeutas (
  id int NOT NULL AUTO_INCREMENT,
  activo bit(1) NOT NULL,
  color varchar(9) DEFAULT NULL,
  especialidad varchar(120) DEFAULT NULL,
  nombre varchar(120) NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE salas (
  id int NOT NULL AUTO_INCREMENT,
  activo bit(1) NOT NULL,
  nombre varchar(80) NOT NULL,
  tipo varchar(80) DEFAULT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- estado: PENDIENTE_PAGO (horario apartado 10 min) → PROGRAMADA → EN_ATENCION → ATENDIDA
--         CANCELADA (con motivo) · EXPIRADA (no se pagó a tiempo; horario liberado)
CREATE TABLE reservas (
  id int NOT NULL AUTO_INCREMENT,
  cliente_id int NOT NULL,
  estado varchar(30) NOT NULL,
  fecha_creacion datetime(6) NOT NULL,
  fecha_hora_fin datetime(6) NOT NULL,
  fecha_hora_inicio datetime(6) NOT NULL,
  notas varchar(500) DEFAULT NULL,
  precio_total decimal(10,2) NOT NULL,
  fisioterapeuta_id int DEFAULT NULL,
  hora_llegada datetime(6) DEFAULT NULL,
  sala_id int DEFAULT NULL,
  expira_en datetime(6) DEFAULT NULL,
  fecha_pago datetime(6) DEFAULT NULL,
  metodo_pago varchar(20) DEFAULT NULL,
  orden_codigo varchar(20) DEFAULT NULL,
  pago_referencia varchar(60) DEFAULT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE reserva_servicios (
  id int NOT NULL AUTO_INCREMENT,
  duracion_minutos int NOT NULL,
  fecha_creacion datetime(6) NOT NULL,
  precio_servicio decimal(10,2) NOT NULL,
  servicio_id int NOT NULL,
  reserva_id int NOT NULL,
  PRIMARY KEY (id),
  KEY FKdqvdw6qef7qnxcs9w2ib54yte (reserva_id),
  CONSTRAINT FKdqvdw6qef7qnxcs9w2ib54yte FOREIGN KEY (reserva_id) REFERENCES reservas (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE notas_clinicas (
  id int NOT NULL AUTO_INCREMENT,
  cliente_id int NOT NULL,
  evolucion varchar(2000) DEFAULT NULL,
  fecha datetime(6) NOT NULL,
  fisioterapeuta_id int DEFAULT NULL,
  motivo varchar(200) NOT NULL,
  nivel_dolor int DEFAULT NULL,
  plan varchar(1000) DEFAULT NULL,
  reserva_id int DEFAULT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;



-- Citas: cada INSERT se omite si su fecha cae en domingo (la clínica no atiende)



-- Notas de evolución (solo de citas que existen)

-- ────────────────────────────────────────────────────────────────────
--  4. CARRITO (Micro-Carrito) · máximo 4 sesiones por compra
-- ────────────────────────────────────────────────────────────────────
USE fisiomarca_carrito;

CREATE TABLE carritos (
  id int NOT NULL AUTO_INCREMENT,
  cliente_id int NOT NULL,
  fecha_creacion datetime(6) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY UKf7xpwf4434eyfx1p8po60nqg2 (cliente_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE carrito_items (
  id int NOT NULL AUTO_INCREMENT,
  cantidad int NOT NULL,
  precio_unitario decimal(10,2) NOT NULL,
  servicio_id int NOT NULL,
  subtotal decimal(10,2) NOT NULL,
  carrito_id int NOT NULL,
  PRIMARY KEY (id),
  KEY FKrtdnie5q1ntdbm7edy7n7fmvd (carrito_id),
  CONSTRAINT FKrtdnie5q1ntdbm7edy7n7fmvd FOREIGN KEY (carrito_id) REFERENCES carritos (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Tres pacientes con compras a medio armar (para mostrar el carrito desplegable)


SET FOREIGN_KEY_CHECKS = 1;

-- ────────────────────────────────────────────────────────────────────
--  Verificación rápida
-- ────────────────────────────────────────────────────────────────────
SELECT 'usuarios' AS tabla, COUNT(*) AS filas FROM fisiomarca_usuarios.usuarios
UNION ALL SELECT 'servicios', COUNT(*) FROM fisiomarca_catalogo.servicios
UNION ALL SELECT 'reservas', COUNT(*) FROM fisiomarca_reservas.reservas
UNION ALL SELECT 'pagadas online', COUNT(*) FROM fisiomarca_reservas.reservas WHERE fecha_pago IS NOT NULL
UNION ALL SELECT 'pago pendiente (10 min)', COUNT(*) FROM fisiomarca_reservas.reservas WHERE estado = 'PENDIENTE_PAGO'
UNION ALL SELECT 'compras expiradas', COUNT(*) FROM fisiomarca_reservas.reservas WHERE estado = 'EXPIRADA'
UNION ALL SELECT 'notas_clinicas', COUNT(*) FROM fisiomarca_reservas.notas_clinicas
UNION ALL SELECT 'items en carritos', COUNT(*) FROM fisiomarca_carrito.carrito_items;
